// ===================== runtime structure builders =====================
template<std::size_t N>
const std::vector<std::string_view>& GetSorted(const std::string_view (&a)[N]) {
  static const std::vector<std::string_view> v = [&] {
    std::vector<std::string_view> r(a, a + N);
    absl::c_sort(r);
    return r;
  }();
  return v;
}
template<std::size_t N>
const std::vector<std::string_view>& GetSortedCI(
  const std::string_view (&a)[N]) {
  static const std::vector<std::string_view> v = [&] {
    std::vector<std::string_view> r(a, a + N);
    absl::c_sort(r, [](std::string_view x, std::string_view y) {
      return StringUtil::CILessThan(x, y);
    });
    return r;
  }();
  return v;
}
template<std::size_t N>
const std::unordered_set<std::string>& GetStdCs(
  const std::string_view (&a)[N]) {
  static const std::unordered_set<std::string> s(a, a + N);
  return s;
}
template<std::size_t N>
const std::unordered_set<std::string, CaseInsensitiveStringHashFunction,
                         CaseInsensitiveStringEquality>&
GetStdCi(const std::string_view (&a)[N]) {
  static const std::unordered_set<std::string,
                                  CaseInsensitiveStringHashFunction,
                                  CaseInsensitiveStringEquality>
    s(a, a + N);
  return s;
}
template<std::size_t N>
const absl::flat_hash_set<std::string>& GetAbslFlatCs(
  const std::string_view (&a)[N]) {
  static const absl::flat_hash_set<std::string> s(a, a + N);
  return s;
}
template<std::size_t N>
const absl::flat_hash_set<std::string, CaseInsensitiveStringHashFunction,
                          CaseInsensitiveStringEquality>&
GetAbslFlatCi(const std::string_view (&a)[N]) {
  static const absl::flat_hash_set<std::string,
                                   CaseInsensitiveStringHashFunction,
                                   CaseInsensitiveStringEquality>
    s(a, a + N);
  return s;
}
template<std::size_t N>
const duckdb::unordered_set<std::string>& GetAbslNodeCs(
  const std::string_view (&a)[N]) {
  static const duckdb::unordered_set<std::string> s(a, a + N);
  return s;
}
template<std::size_t N>
const duckdb::case_insensitive_set_t& GetAbslNodeCi(
  const std::string_view (&a)[N]) {
  static const duckdb::case_insensitive_set_t s(a, a + N);
  return s;
}
template<std::size_t N>
const absl::flat_hash_set<std::string_view>& GetAbslFlatViewCs(
  const std::string_view (&a)[N]) {
  static const absl::flat_hash_set<std::string_view> s(a, a + N);
  return s;
}
template<std::size_t N>
const duckdb::case_insensitive_set_view_t& GetAbslFlatViewCi(
  const std::string_view (&a)[N]) {
  static const duckdb::case_insensitive_set_view_t s(a, a + N);
  return s;
}
template<typename SetT, std::size_t N>
SetT MakeStringTSet(const std::string_view (&a)[N]) {
  SetT s;
  for (auto v : a) {
    s.emplace(v.data(), static_cast<uint32_t>(v.size()));
  }
  return s;
}
using StringTCsSet = absl::flat_hash_set<duckdb::string_t, duckdb::StringHash,
                                         duckdb::StringEquality>;
using StringTCiSet = absl::flat_hash_set<duckdb::string_t, duckdb::StringCIHash,
                                         duckdb::StringCIEquality>;
template<std::size_t N>
const StringTCsSet& GetAbslFlatStringTCs(const std::string_view (&a)[N]) {
  static const StringTCsSet s = MakeStringTSet<StringTCsSet>(a);
  return s;
}
template<std::size_t N>
const StringTCiSet& GetAbslFlatStringTCi(const std::string_view (&a)[N]) {
  static const StringTCiSet s = MakeStringTSet<StringTCiSet>(a);
  return s;
}
// "bad CI": NATIVE (case-sensitive) hash + CIEquals. Intentionally inconsistent
// (equal keys hash to different buckets), so mixed-case hits MISS -- this is
// NOT a correct CI set. It exists only to isolate the CIHash cost: its speed ~=
// native hash + miss path, so (real-CI - bad-CI) ~= the per-lookup CIHash
// penalty.
template<std::size_t N>
const std::unordered_set<std::string, std::hash<std::string>,
                         CaseInsensitiveStringEquality>&
GetStdCiBad(const std::string_view (&a)[N]) {
  static const std::unordered_set<std::string, std::hash<std::string>,
                                  CaseInsensitiveStringEquality>
    s(a, a + N);
  return s;
}
template<std::size_t N>
const absl::flat_hash_set<std::string, absl::Hash<std::string>,
                          CaseInsensitiveStringEquality>&
GetAbslFlatCiBad(const std::string_view (&a)[N]) {
  static const absl::flat_hash_set<std::string, absl::Hash<std::string>,
                                   CaseInsensitiveStringEquality>
    s(a, a + N);
  return s;
}
template<std::size_t N>
const duckdb::unordered_set<std::string, absl::Hash<std::string>,
                            CaseInsensitiveStringEquality>&
GetAbslNodeCiBad(const std::string_view (&a)[N]) {
  static const duckdb::unordered_set<std::string, absl::Hash<std::string>,
                                     CaseInsensitiveStringEquality>
    s(a, a + N);
  return s;
}

// ============================ lookup loops ============================
// One lookup per benchmark iteration -> reported Time is ns/lookup (+ a
// constant index/mask shared by every structure, so comparisons are fair).
template<std::size_t N>
void RunLinearCS(benchmark::State& s, const std::string_view (&a)[N],
                 const std::vector<std::string>& q) {
  std::size_t i = 0, m = q.size() - 1;
  for (auto _ : s) {
    i = (i + 1) & m;
    std::string_view key = q[i];
    bool found = false;
    for (std::size_t j = 0; j < N; ++j) {
      if (a[j] == key) {
        found = true;
        break;
      }
    }
    benchmark::DoNotOptimize(found);
  }
}
template<std::size_t N>
void RunLinearCI(benchmark::State& s, const std::string_view (&a)[N],
                 const std::vector<std::string>& q) {
  std::size_t i = 0, m = q.size() - 1;
  for (auto _ : s) {
    i = (i + 1) & m;
    std::string_view key = q[i];
    bool found = false;
    for (std::size_t j = 0; j < N; ++j) {
      if (StringUtil::CIEquals(a[j], key)) {
        found = true;
        break;
      }
    }
    benchmark::DoNotOptimize(found);
  }
}
void RunSortedCS(benchmark::State& s, const std::vector<std::string_view>& v,
                 const std::vector<std::string>& q) {
  std::size_t i = 0, m = q.size() - 1;
  for (auto _ : s) {
    i = (i + 1) & m;
    bool found = std::binary_search(v.begin(), v.end(), std::string_view(q[i]));
    benchmark::DoNotOptimize(found);
  }
}
void RunSortedCI(benchmark::State& s, const std::vector<std::string_view>& v,
                 const std::vector<std::string>& q) {
  std::size_t i = 0, m = q.size() - 1;
  for (auto _ : s) {
    i = (i + 1) & m;
    std::string_view key = q[i];
    auto it = std::lower_bound(v.begin(), v.end(), key,
                               [](std::string_view x, std::string_view y) {
                                 return StringUtil::CILessThan(x, y);
                               });
    bool found = it != v.end() && StringUtil::CIEquals(*it, key);
    benchmark::DoNotOptimize(found);
  }
}
// Look up the std::string key directly: each hash set uses ITS OWN default
// hash/eq for CS, and DuckDB's CIHash/CIEquals for CI. count(const string&) is
// exact-key (no transparency needed), zero-copy.
template<typename SetT>
void RunHash(benchmark::State& s, const SetT& set,
             const std::vector<std::string>& q) {
  std::size_t i = 0, m = q.size() - 1;
  for (auto _ : s) {
    i = (i + 1) & m;
    benchmark::DoNotOptimize(set.count(q[i]));
  }
}
template<typename SetT>
void RunHashStringT(benchmark::State& s, const SetT& set,
                    const std::vector<std::string>& q) {
  std::size_t i = 0, m = q.size() - 1;
  for (auto _ : s) {
    i = (i + 1) & m;
    benchmark::DoNotOptimize(set.count(
      duckdb::string_t(q[i].data(), static_cast<uint32_t>(q[i].size()))));
  }
}
template<typename SetT>
void RunTrivCs(benchmark::State& s, const SetT& set,
               const std::vector<std::string>& q) {
  std::size_t i = 0, m = q.size() - 1;
  for (auto _ : s) {
    i = (i + 1) & m;
    benchmark::DoNotOptimize(set.Contains(std::string_view(q[i])));
  }
}
template<typename SetT>
void RunTrivCi(benchmark::State& s, const SetT& set,
               const std::vector<std::string>& q) {
  std::size_t i = 0, m = q.size() - 1;
  for (auto _ : s) {
    i = (i + 1) & m;
    benchmark::DoNotOptimize(set.ContainsICase(std::string_view(q[i])));
  }
}
